// Problem RFC 9457 problem details with a stable `code`.
type Problem struct {
	// Code Stable machine-readable error code. The web app maps each one to an i18n message.
	//
	// | Status | Codes |
	// |---|---|
	// | 400 | `validation.failed`, `auth.invalid_email`, `auth.invalid_name`, `auth.weak_password`, `pact.invalid_terms`, `pact.terms_members`, `proof.invalid_doc`, `checkin.reason_required`, `upload.size_mismatch` |
	// | 401 | `auth.unauthenticated`, `auth.invalid_credentials` |
	// | 403 | `auth.csrf`, `pact.not_backer`, `pact.not_doer`, `checkin.not_allowed` |
	// | 404 | `not_found` (also for non-members) |
	// | 405 | `method_not_allowed` |
	// | 409 | `auth.email_taken`, `pact.invalid_state`, `pact.terms_mismatch`, `pact.member_missing`, `pact.start_passed`, `pact.limit_reached`, `checkin.invalid_transition`, `checkin.conflict`, `checkin.override_limit`, `checkin.rest_limit`, `upload.quota_exceeded`, `idempotency.in_progress` |
	// | 410 | `pact.invite_invalid` |
	// | 413 | `upload.too_large`, `request.too_large` |
	// | 415 | `upload.unsupported_type`, `request.unsupported_media_type` |
	// | 422 | `pact.signature_mismatch`, `checkin.deadline_passed`, `checkin.evidence_insufficient`, `idempotency.key_reused` |
	// | 429 | `rate_limited`, `auth.rate_limited` |
	// | 500 | `server.internal` |
	// | 503 | `upload.queue_busy`, `server.unavailable` |
	Code   ErrorCode `json:"code"`
	Detail *string   `json:"detail,omitempty"`

	// Errors Per-field detail, present for `validation.failed` and `pact.invalid_terms`.
	Errors   *[]FieldError `json:"errors,omitempty"`
	Instance *string       `json:"instance,omitempty"`

	// RequestId Echo of the `X-Request-Id` header, for support.
	RequestId *string `json:"request_id,omitempty"`
	Status    int     `json:"status"`

	// Title A short English summary. Not for display.
	Title string `json:"title"`

	// Type A URI naming the problem type. `about:blank` when `code` says it all.
	Type string `json:"type"`
}

