// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Post(options.BaseURL+"/auth/register", wrapper.Register)

	router.Post(options.BaseURL+"/auth/login", wrapper.Login)

	router.Post(options.BaseURL+"/auth/logout", wrapper.Logout)

	router.Get(options.BaseURL+"/me", wrapper.GetMe)

	router.Patch(options.BaseURL+"/me", wrapper.UpdateMe)

	router.Get(options.BaseURL+"/today", wrapper.GetToday)

	router.Get(options.BaseURL+"/pacts", wrapper.ListPacts)

	router.Post(options.BaseURL+"/pacts", wrapper.CreatePact)

	router.Get(options.BaseURL+"/pacts/:pactId", wrapper.GetPact)

	router.Patch(options.BaseURL+"/pacts/:pactId", wrapper.UpdatePact)

	router.Post(options.BaseURL+"/pacts/:pactId/propose", wrapper.ProposePact)

	router.Post(options.BaseURL+"/pacts/:pactId/accept", wrapper.AcceptPact)

	router.Get(options.BaseURL+"/invites/:token", wrapper.PreviewInvite)

	router.Post(options.BaseURL+"/invites/:token/join", wrapper.JoinInvite)

	router.Get(options.BaseURL+"/pacts/:pactId/check-ins", wrapper.ListPactCheckIns)

	router.Get(options.BaseURL+"/check-ins/:checkInId", wrapper.GetCheckIn)

	router.Put(options.BaseURL+"/check-ins/:checkInId/proof", wrapper.SubmitProof)

	router.Post(options.BaseURL+"/check-ins/:checkInId/rest", wrapper.DeclareRest)

	router.Post(options.BaseURL+"/check-ins/:checkInId/approve", wrapper.ApproveCheckIn)

	router.Post(options.BaseURL+"/check-ins/:checkInId/reject", wrapper.RejectCheckIn)

	router.Post(options.BaseURL+"/check-ins/:checkInId/override", wrapper.OverrideCheckIn)

	router.Post(options.BaseURL+"/check-ins/:checkInId/dispute", wrapper.DisputeCheckIn)

	router.Post(options.BaseURL+"/check-ins/:checkInId/dispute/resolve", wrapper.ResolveDispute)

	router.Get(options.BaseURL+"/review-queue", wrapper.GetReviewQueue)

	router.Get(options.BaseURL+"/pacts/:pactId/ledger", wrapper.ListLedger)

	router.Post(options.BaseURL+"/pacts/:pactId/payout/mark-paid", wrapper.MarkPayoutPaid)

	router.Post(options.BaseURL+"/pacts/:pactId/payout/confirm", wrapper.ConfirmPayout)

	router.Post(options.BaseURL+"/uploads", wrapper.CreateUpload)

	router.Post(options.BaseURL+"/uploads/:attachmentId/complete", wrapper.CompleteUpload)

	router.Get(options.BaseURL+"/attachments/:attachmentId", wrapper.GetAttachment)

	router.Get(options.BaseURL+"/notifications", wrapper.ListNotifications)

	router.Post(options.BaseURL+"/notifications/read", wrapper.MarkNotificationsRead)

}

